<span class="line"><span style="color:#E1E4E8;">        System.out.</span><span style="color:#B392F0;">println</span><span style="color:#E1E4E8;">(</span><span style="color:#9ECBFF;">&quot;   用户表加密规则: &quot;</span><span style="color:#F97583;"> +</span><span style="color:#E1E4E8;"> userCollectionRule);</span></span>
